import{_ as a,o as l,c as i,ag as o}from"./chunks/framework.ePeAWSvT.js";const e="/images/link-01.png",r="/images/link-02.png",s="/images/link-03.png",n="/images/link-04.png",b=JSON.parse('{"title":"链接一键记","description":"","frontmatter":{},"headers":[],"relativePath":"capture/link.md","filePath":"capture/link.md","lastUpdated":null}'),d={name:"capture/link.md"};function u(c,t,p,h,m,q){return l(),i("div",null,[...t[0]||(t[0]=[o('<h1 id="链接一键记" tabindex="-1">链接一键记 <a class="header-anchor" href="#链接一键记" aria-label="Permalink to &quot;链接一键记&quot;">​</a></h1><p>Get 笔记支持导入多种类型的链接，AI 自动提取精华内容。</p><h2 id="支持的链接类型" tabindex="-1">支持的链接类型 <a class="header-anchor" href="#支持的链接类型" aria-label="Permalink to &quot;支持的链接类型&quot;">​</a></h2><ul><li><strong>图文链接</strong>：微信公众号文章、小红书图文、公开免费网站等</li><li><strong>视频链接</strong>：抖音短视频、B站视频、小红书视频、得到直播回放等</li></ul><h2 id="公众号文章" tabindex="-1">公众号文章 <a class="header-anchor" href="#公众号文章" aria-label="Permalink to &quot;公众号文章&quot;">​</a></h2><ol><li>点击一篇公众号文章，在右上角...中选择复制链接</li><li>打开 Get 笔记 APP，点击底部 + 号，选择&quot;粘贴链接&quot;</li><li>粘贴链接后，可以在链接下方添加补充信息和要求</li><li>点击&quot;确定&quot;，AI 会读取文章内容并帮你记录总结重点信息</li></ol><div class="tip custom-block"><p class="custom-block-title">提示</p><p>若链接中包含多张图片，AI可理解到10张图，且图片理解的能力也会随AI能力的发展逐步增强。</p></div><h2 id="抖音短视频" tabindex="-1">抖音短视频 <a class="header-anchor" href="#抖音短视频" aria-label="Permalink to &quot;抖音短视频&quot;">​</a></h2><ol><li>点开一个抖音短视频，在右下角点击分享按钮，选择&quot;分享链接&quot;，然后复制链接</li><li>打开 Get 笔记 APP，点击底部 + 号，选择&quot;粘贴链接&quot;</li><li>粘贴链接后，AI 会自动提取其中的 url</li><li>点击&quot;确定&quot;，AI 会读取短视频内容并帮你记录总结重点信息</li></ol><h2 id="小红书图文-短视频" tabindex="-1">小红书图文/短视频 <a class="header-anchor" href="#小红书图文-短视频" aria-label="Permalink to &quot;小红书图文/短视频&quot;">​</a></h2><ol><li>点开一个小红书图文/短视频，点击分享按钮，然后复制链接</li><li>打开 Get 笔记 APP，点击底部 + 号，选择&quot;粘贴链接&quot;</li><li>如果图片中有文字，也会识别图片中的文字，并进行整理</li><li>点击&quot;确定&quot;，AI 会读取内容并帮你记录总结</li></ol><h2 id="b站视频" tabindex="-1">B站视频 <a class="header-anchor" href="#b站视频" aria-label="Permalink to &quot;B站视频&quot;">​</a></h2><ol><li>点开一个 B 站视频，再点击分享按钮，然后复制链接</li><li>打开 Get 笔记 APP，点击底部 + 号，选择&quot;粘贴链接&quot;</li><li>点击&quot;确定&quot;，AI 会读取视频内容并帮你记录总结</li></ol><div class="warning custom-block"><p class="custom-block-title">温馨提醒</p><p>如果视频时长过长（如2小时），AI 处理等待时间会较长，可以先收起处理页面，继续进行其他操作，AI 依然会在后台继续处理。</p></div><h2 id="截图演示" tabindex="-1">截图演示 <a class="header-anchor" href="#截图演示" aria-label="Permalink to &quot;截图演示&quot;">​</a></h2><div style="display:flex;gap:10px;overflow-x:auto;padding:10px 0;"><img src="'+e+'" alt="粘贴链接入口" style="width:180px;border-radius:8px;"><img src="'+r+'" alt="链接识别" style="width:180px;border-radius:8px;"><img src="'+s+'" alt="AI处理中" style="width:180px;border-radius:8px;"><img src="'+n+'" alt="生成笔记" style="width:180px;border-radius:8px;"></div>',16)])])}const x=a(d,[["render",u]]);export{b as __pageData,x as default};
